539	func (r *Registry) checkTransfer(req TransferRequest) error {
540		h, ok := r.state.Holdings[req.ItemID]
541		if !ok {
542			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
543				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
544			}
545			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
546		}
547		op, ok := r.state.Accounts[req.Operator]
548		if !ok {
549			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
550		}
551		if !op.Active {
552			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
553		}
554		to, ok := r.state.Accounts[req.ToID]
555		if !ok {
556			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
557		}
558		if !to.Active {
559			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
560		}
561		if req.ToID == h.OwnerID {
562			return fmt.Errorf("%w: 接收人 %s 已是当前持有人", ErrSameAccount, req.ToID)
563		}
564		// 期望持有人或期望版本不符，包括发起人并非当前持有人的情况。
565		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
566			req.Operator != h.OwnerID {
567			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d", ErrConflict,
568				req.ItemID, h.OwnerID, h.Version)
569		}
570		return nil
571	}
572	
573	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
574		if prev.Kind != "transfer" || prev.Params != sig {
575			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
576				ErrRequestConflict, prev.Operator, prev.RequestID)
577		}
578		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
579			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
580		if prev.Rejected {
581			res.Err = codeErr(prev.Reason)
582			return res, res.Err
583		}
584		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
585		// 价款与应付明细，不重复计入。
586		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
587		return res, nil
588	}
