592	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
593	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
594	func authzCurrentStatus(a authzRec, now time.Time) string {
595		switch a.Status {
596		case "revoked":
597			return AuthRevoked
598		case "used":
599			return AuthUsed
600		}
601		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
602			return AuthExpired
603		}
604		return AuthActive
605	}
