607	func (req CreateAuthorizationRequest) validatePresent() error {
608		missing := []string{}
609		if strings.TrimSpace(req.Operator) == "" {
610			missing = append(missing, "operator")
611		}
612		if strings.TrimSpace(req.Reason) == "" {
613			missing = append(missing, "reason")
614		}
615		if strings.TrimSpace(req.RequestID) == "" {
616			missing = append(missing, "request_id")
617		}
618		if strings.TrimSpace(req.AuthID) == "" {
619			missing = append(missing, "auth_id")
620		}
621		if strings.TrimSpace(req.ItemID) == "" {
622			missing = append(missing, "item_id")
623		}
624		if strings.TrimSpace(req.TrusteeID) == "" {
625			missing = append(missing, "trustee_id")
626		}
627		if strings.TrimSpace(req.ToID) == "" {
628			missing = append(missing, "to_id")
629		}
630		if strings.TrimSpace(req.ExpectedOwner) == "" {
631			missing = append(missing, "expected_owner")
632		}
633		if req.ExpectedVer <= 0 {
634			missing = append(missing, "expected_version")
635		}
636		if req.ExpiresAt.IsZero() {
637			missing = append(missing, "expires_at")
638		}
639		if len(missing) > 0 {
640			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
641		}
642		if req.Price < 0 {
643			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
644		}
645		return nil
646	}
