648	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
649		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
650		// 仍可回放；改价则按请求号冲突拒绝。
651		b, _ := json.Marshal(struct {
652			Kind          string `json:"kind"`
653			AuthID        string `json:"auth_id"`
654			ItemID        string `json:"item_id"`
655			TrusteeID     string `json:"trustee_id"`
656			ToID          string `json:"to_id"`
657			ExpectedOwner string `json:"expected_owner"`
658			ExpectedVer   int64  `json:"expected_version"`
659			ExpiresAt     string `json:"expires_at"`
660			Price         int64  `json:"price,omitempty"`
661			Reason        string `json:"reason"`
662		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
663			req.ExpectedOwner, req.ExpectedVer,
664			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
665		return string(b)
666	}
