668	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
669	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
670	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
671	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
672	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
673	//
674	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
675	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
676	// 参数错误与引用不存在不占用请求号。
677	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
678		if err := req.validatePresent(); err != nil {
679			return CreateAuthorizationResult{}, err
680		}
681		r.mu.Lock()
682		defer r.mu.Unlock()
683		if err := r.checkOpen(); err != nil {
684			return CreateAuthorizationResult{}, err
685		}
686	
687		now := r.now()
688		key := requestKey(req.Operator, req.RequestID)
689		sig := createAuthzParamsSig(req)
690		if prev, ok := r.state.Requests[key]; ok {
691			return r.replayCreateAuthz(prev, sig)
692		}
693	
694		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
695			if !isValidationErr(bizErr) {
696				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
697				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
698				r.state.Requests[key] = request{
699					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
700					Params: sig, Rejected: true, Reason: errCode(bizErr),
701					AuthID: req.AuthID, ItemID: req.ItemID,
702				}
703				_ = r.commit()
704			}
705			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
706		}
707	
708		h := r.state.Holdings[req.ItemID]
709		a := authzRec{
710			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
711			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
712			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
713		}
714		r.state.Authzs[req.AuthID] = a
715		authSeq := r.state.NextAuthSeq + 1
716		r.state.NextAuthSeq = authSeq
717		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
718			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
719			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
720			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
721		})
722		r.state.Requests[key] = request{
723			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
724			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
725		}
726		if err := r.commit(); err != nil {
727			return CreateAuthorizationResult{}, err
728		}
729		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
730	}
731	
732	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
733		h, ok := r.state.Holdings[req.ItemID]
734		if !ok {
735			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
736				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
737			}
738			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
739		}
740		op, ok := r.state.Accounts[req.Operator]
741		if !ok {
742			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
743		}
744		trustee, ok := r.state.Accounts[req.TrusteeID]
745		if !ok {
746			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
747		}
748		to, ok := r.state.Accounts[req.ToID]
749		if !ok {
750			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
751		}
752		if req.TrusteeID == req.Operator {
753			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
754		}
755		if req.ToID == req.Operator {
756			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
757		}
758		if !op.Active {
759			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
760		}
761		if !trustee.Active {
762			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
763		}
764		if !to.Active {
765			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
766		}
767		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
768		if _, exists := r.state.Authzs[req.AuthID]; exists {
769			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
770		}
771		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
772		if !req.ExpiresAt.After(now) {
773			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
774				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
775		}
776		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
777			req.Operator != h.OwnerID {
778			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
779				ErrConflict, req.ItemID, h.OwnerID, h.Version)
780		}
781		return nil
782	}
