784	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
785		if prev.Kind != "auth_create" || prev.Params != sig {
786			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
787				ErrRequestConflict, prev.Operator, prev.RequestID)
788		}
789		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
790			Status: AuthActive, Replayed: true}
791		if prev.Rejected {
792			res.Err = codeErr(prev.Reason)
793			return res, res.Err
794		}
795		return res, nil
796	}
797	
798	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
799		b, _ := json.Marshal(struct {
800			Kind   string `json:"kind"`
801			AuthID string `json:"auth_id"`
802			Reason string `json:"reason"`
803		}{"auth_revoke", req.AuthID, req.Reason})
804		return string(b)
805	}
806	
807	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
808	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
809	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
810	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
811		missing := []string{}
812		if strings.TrimSpace(req.Operator) == "" {
813			missing = append(missing, "operator")
814		}
815		if strings.TrimSpace(req.Reason) == "" {
816			missing = append(missing, "reason")
817		}
818		if strings.TrimSpace(req.RequestID) == "" {
819			missing = append(missing, "request_id")
820		}
821		if strings.TrimSpace(req.AuthID) == "" {
822			missing = append(missing, "auth_id")
823		}
824		if len(missing) > 0 {
825			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
826				ErrInvalidArgument, strings.Join(missing, ", "))
827		}
828		r.mu.Lock()
829		defer r.mu.Unlock()
830		if err := r.checkOpen(); err != nil {
831			return RevokeAuthorizationResult{}, err
832		}
833	
834		now := r.now()
835		key := requestKey(req.Operator, req.RequestID)
836		sig := revokeAuthzParamsSig(req)
837		if prev, ok := r.state.Requests[key]; ok {
838			return r.replayRevokeAuthz(prev, sig)
839		}
840	
841		a, ok := r.state.Authzs[req.AuthID]
842		if !ok {
843			// 引用不存在不占用请求号。
844			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
845			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
846		}
847		if a.GranterID != req.Operator {
848			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
849				ErrForbidden, a.GranterID, req.AuthID)
850			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
851			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
852		}
853		switch authzCurrentStatus(a, now) {
854		case AuthUsed:
855			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
856			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
857			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
858		case AuthRevoked:
859			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
860			// 相同请求重放回放同一结果。
861			r.state.Requests[key] = request{
862				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
863				Params: sig, AuthID: req.AuthID,
864			}
865			if err := r.commit(); err != nil {
866				return RevokeAuthorizationResult{}, err
867			}
868			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
869		}
870	
871		from := AuthActive
872		if authzCurrentStatus(a, now) == AuthExpired {
873			from = AuthExpired
874		}
875		a.Status = "revoked"
876		a.RevokedAt = now
877		r.state.Authzs[req.AuthID] = a
878		authSeq := r.state.NextAuthSeq + 1
879		r.state.NextAuthSeq = authSeq
880		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
881			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
882			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
883			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
884		})
885		r.state.Requests[key] = request{
886			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
887			Params: sig, AuthID: req.AuthID,
888		}
889		if err := r.commit(); err != nil {
890			return RevokeAuthorizationResult{}, err
891		}
892		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
893	}
894	
895	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
896	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
897		r.state.Requests[key] = request{
898			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
899			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
900		}
901		_ = r.commit()
902	}
903	
904	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
905		if prev.Kind != "auth_revoke" || prev.Params != sig {
906			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
907				ErrRequestConflict, prev.Operator, prev.RequestID)
908		}
909		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
910		if prev.Rejected {
911			res.Err = codeErr(prev.Reason)
912			res.Status = ""
913			return res, res.Err
914		}
915		return res, nil
916	}
917	
918	func proxyTransferParamsSig(req ProxyTransferRequest) string {
919		b, _ := json.Marshal(struct {
920			Kind   string `json:"kind"`
921			AuthID string `json:"auth_id"`
922			Reason string `json:"reason"`
923		}{"proxy_transfer", req.AuthID, req.Reason})
924		return string(b)
925	}
926	
927	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
928	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
929	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
930	// 操作者记为实际受托账户并可通过授权编号追溯。
931	//
932	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
933	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
934	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
935	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
936	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
937	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
938	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
939		missing := []string{}
940		if strings.TrimSpace(req.Operator) == "" {
941			missing = append(missing, "operator")
942		}
943		if strings.TrimSpace(req.Reason) == "" {
944			missing = append(missing, "reason")
945		}
946		if strings.TrimSpace(req.RequestID) == "" {
947			missing = append(missing, "request_id")
948		}
949		if strings.TrimSpace(req.AuthID) == "" {
950			missing = append(missing, "auth_id")
951		}
952		if len(missing) > 0 {
953			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
954				ErrInvalidArgument, strings.Join(missing, ", "))
955		}
956		r.mu.Lock()
957		defer r.mu.Unlock()
958		if err := r.checkOpen(); err != nil {
959			return ProxyTransferResult{}, err
960		}
961	
962		now := r.now()
963		key := requestKey(req.Operator, req.RequestID)
964		sig := proxyTransferParamsSig(req)
965		if prev, ok := r.state.Requests[key]; ok {
966			return r.replayProxyTransfer(prev, sig)
967		}
968	
969		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
970			if !isValidationErr(bizErr) {
971				r.state.Requests[key] = request{
972					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
973					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
974				}
975				_ = r.commit()
976			}
977			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
978		}
979	
980		a := r.state.Authzs[req.AuthID]
981		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
982		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
983		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
984		// 追溯。
985		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
986		a.Status = "used"
987		a.UsedTxSeq = out.seq
988		a.UsedAt = now
989		r.state.Authzs[a.ID] = a
990		authSeq := r.state.NextAuthSeq + 1
991		r.state.NextAuthSeq = authSeq
992		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
993			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
994			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
995			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
996		})
997		r.state.Requests[key] = request{
998			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
999			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1000			Version: out.toVer(), TxSeq: out.seq,
1001		}
1002		if err := r.commit(); err != nil {
1003			return ProxyTransferResult{}, err
1004		}
1005		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1006			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1007			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1008			Remainder: out.royalty.Remainder}, nil
1009	}
1010	
1011	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1012		a, ok := r.state.Authzs[req.AuthID]
1013		if !ok {
1014			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1015		}
1016		op, ok := r.state.Accounts[req.Operator]
1017		if !ok {
1018			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1019		}
1020		granter, gOk := r.state.Accounts[a.GranterID]
1021		to, tOk := r.state.Accounts[a.ToID]
1022		if req.Operator != a.TrusteeID {
1023			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1024				ErrForbidden, req.Operator, req.AuthID)
1025		}
1026		if !gOk {
1027			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1028		}
1029		if !tOk {
1030			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1031		}
1032		if !op.Active {
1033			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1034		}
1035		if !granter.Active {
1036			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1037		}
1038		if !to.Active {
1039			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1040		}
1041		switch authzCurrentStatus(a, now) {
1042		case AuthRevoked:
1043			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1044		case AuthExpired:
1045			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1046		case AuthUsed:
1047			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1048		}
1049		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1050		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1051		h, ok := r.state.Holdings[a.ItemID]
1052		if !ok {
1053			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1054		}
1055		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1056			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1057				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1058		}
1059		return nil
1060	}
1061	
1062	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1063		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1064			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1065				ErrRequestConflict, prev.Operator, prev.RequestID)
1066		}
1067		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1068			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1069		if prev.Rejected {
1070			res.Err = codeErr(prev.Reason)
1071			return res, res.Err
1072		}
1073		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1074		// 原价款与应付明细，不重复计入。
1075		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1076		return res, nil
1077	}
1078	
1079	// ---- 授权查询 ----
1080	
1081	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1082	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1083	// 到期但尚未终结的授权返回 AuthExpired。
1084	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1085		r.mu.Lock()
1086		defer r.mu.Unlock()
1087		if err := r.checkOpen(); err != nil {
1088			return Authorization{}, err
1089		}
1090		a, ok := r.state.Authzs[authID]
1091		if !ok {
1092			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1093		}
1094		return Authorization{
1095			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1096			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1097			Status:    authzCurrentStatus(a, r.now()),
1098			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1099			RevokedAt: a.RevokedAt,
1100		}, nil
1101	}
1102	
1103	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1104	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1105	// 不存在时返回包裹 ErrNotFound 的错误。
1106	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1107		r.mu.Lock()
1108		defer r.mu.Unlock()
1109		if err := r.checkOpen(); err != nil {
1110			return nil, err
1111		}
1112		if _, ok := r.state.Items[itemID]; !ok {
1113			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1114		}
1115		out := make([]AuthorizationEvent, 0)
1116		for _, e := range r.state.AuthEvents {
1117			if e.ItemID != itemID {
1118				continue
1119			}
1120			out = append(out, AuthorizationEvent{
1121				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1122				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1123				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1124				OccurredAt: e.OccurredAt,
1125			})
1126		}
1127		return out, nil
1128	}
1129	
1130	// ---- 查询 ----
1131	
1132	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1133	func (r *Registry) GetItem(id string) (Item, error) {
1134		r.mu.Lock()
1135		defer r.mu.Unlock()
1136		if err := r.checkOpen(); err != nil {
1137			return Item{}, err
1138		}
1139		it, ok := r.state.Items[id]
1140		if !ok {
1141			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1142		}
1143		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1144			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1145	}
1146	
1147	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1148	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1149		r.mu.Lock()
1150		defer r.mu.Unlock()
1151		if err := r.checkOpen(); err != nil {
1152			return Holding{}, err
1153		}
1154		h, ok := r.state.Holdings[itemID]
1155		if !ok {
1156			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1157		}
1158		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1159	}
1160	
1161	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1162	// ErrNotFound 的错误；停用账户仍可正常查询。
1163	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1164		r.mu.Lock()
1165		defer r.mu.Unlock()
1166		if err := r.checkOpen(); err != nil {
1167			return nil, err
1168		}
1169		if _, ok := r.state.Accounts[accountID]; !ok {
1170			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1171		}
1172		out := make([]Holding, 0)
1173		for _, h := range r.state.Holdings {
1174			if h.OwnerID == accountID {
1175				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1176			}
1177		}
1178		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1179		return out, nil
1180	}
1181	
1182	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1183	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1184	// 返回包裹 ErrNotFound 的错误。
1185	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1186		r.mu.Lock()
1187		defer r.mu.Unlock()
1188		if err := r.checkOpen(); err != nil {
1189			return nil, err
1190		}
1191		if _, ok := r.state.Items[itemID]; !ok {
1192			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1193		}
1194		out := make([]HistoryEntry, 0)
1195		for _, e := range r.state.History {
1196			if e.ItemID != itemID {
1197				continue
1198			}
1199			out = append(out, HistoryEntry{
1200				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1201				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1202				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1203			})
1204		}
1205		return out, nil
1206	}
1207	
1208	// ---- 幂等辅助 ----
1209	
1210	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1211	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1212	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1213	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1214	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1215	func requestKey(operator, requestID string) string {
1216		b, _ := json.Marshal([2]string{operator, requestID})
1217		return string(b)
1218	}
1219	
1220	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1221	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1222	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1223	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1224	// 并回放。
1225	func isValidationErr(err error) bool {
1226		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1227	}
1228	
1229	var errCodes = map[error]string{
1230		ErrNotFound:             "not_found",
1231		ErrAlreadyExists:        "already_exists",
1232		ErrAccountInactive:      "account_inactive",
1233		ErrSeriesSealed:         "series_sealed",
1234		ErrConflict:             "conflict",
1235		ErrSameAccount:          "same_account",
1236		ErrForbidden:            "forbidden",
1237		ErrAuthorizationRevoked: "authorization_revoked",
1238		ErrAuthorizationExpired: "authorization_expired",
1239		ErrAuthorizationUsed:    "authorization_used",
1240		ErrRoyaltyFrozen:        "royalty_frozen",
1241		ErrSplitIntentRejected:  "split_intent_rejected",
1242		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1243		ErrSplitIntentInvalid:   "split_intent_invalid",
1244		ErrSplitIntentExpired:   "split_intent_expired",
1245		ErrSplitAnswered:        "split_answered",
1246	}
1247	
1248	var codeErrs = map[string]error{
1249		"not_found":              ErrNotFound,
1250		"already_exists":         ErrAlreadyExists,
1251		"account_inactive":       ErrAccountInactive,
1252		"series_sealed":          ErrSeriesSealed,
1253		"conflict":               ErrConflict,
1254		"same_account":           ErrSameAccount,
1255		"forbidden":              ErrForbidden,
1256		"authorization_revoked":  ErrAuthorizationRevoked,
1257		"authorization_expired":  ErrAuthorizationExpired,
1258		"authorization_used":     ErrAuthorizationUsed,
1259		"royalty_frozen":         ErrRoyaltyFrozen,
1260		"split_intent_rejected":  ErrSplitIntentRejected,
1261		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1262		"split_intent_invalid":   ErrSplitIntentInvalid,
1263		"split_intent_expired":   ErrSplitIntentExpired,
1264		"split_answered":         ErrSplitAnswered,
1265	}
1266	
1267	func errCode(err error) string {
1268		for sentinel, code := range errCodes {
1269			if errors.Is(err, sentinel) {
1270				return code
1271			}
1272		}
1273		return "rejected"
1274	}
1275	
1276	func codeErr(code string) error {
1277		if e, ok := codeErrs[code]; ok {
1278			return e
1279		}
1280		return errors.New("registry: 请求曾被拒绝")
1281	}
1282

