		// 期望持有人或期望版本不符，包括操作者并非该件当前持有人的情况；
		// 系列封存不阻止转让，这里不检查封存状态。
		if h.OwnerID != e.ExpectedOwner || h.Version != e.ExpectedVer ||
			req.Operator != h.OwnerID {
			return e.ItemID, fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
				ErrConflict, e.ItemID, h.OwnerID, h.Version)
		}
	}
	return "", nil
}

